// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, uint256 extra, address target) public {
        vm.assume(amount <= type(uint128).max);
        vm.assume(extra <= type(uint128).max);
        vm.assume(target != address(c));
        vm.assume(target != address(this));
        vm.assume(target != address(0));

        vm.deal(address(c), extra);
        vm.deal(c.Owner(), amount + 1 ether);

        uint256 contractBefore = address(c).balance;
        uint256 ownerBefore = c.Owner().balance;

        vm.prank(c.Owner());
        c.Command{value: amount}(target, "");

        uint256 contractAfter = address(c).balance;
        uint256 ownerAfter = c.Owner().balance;

        uint256 ownerLoss = ownerBefore - ownerAfter;
        uint256 contractLoss = contractBefore - contractAfter;
        assertTrue(ownerLoss + contractLoss == amount);
    }
}
